import { CardProps } from "./cardtypes";
import Image from "next/image";
import Link from "next/link";

function Card({ title, description, image }: CardProps) {
  return (
    <div
      className="max-w-sm overflow-hidden shadow-md hover:shadow-lg transition-shadow duration-300 ease-in-out hover:cursor-pointer flex flex-col justify-between rounded-lg p-4 bg-white hover:bg-gray-50 dark:bg-gray-100 dark:hover:bg-gray-200"
      style={{ width: "280px", height: "430px" }}
    >
      <div className="flex flex-col items-center text-center">
        <div className="my-3 w-full flex justify-center">
          <Image
            src={image as string}
            alt="Card Image"
            width={50}
            height={50}
            style={{ objectFit: "cover" }}
            className="rounded-md"
          />
        </div>
        <div className="px-6 py-2 flex-grow">
          <h3 className="font-bold text-xl mb-2 text-gray-800 dark:text-gray-900">
            <div>{title}</div>
          </h3>
          <p className="text-left text-gray-600 dark:text-gray-800">
            <div>{description}</div>
          </p>
        </div>
      </div>
      <div className="mt-4 px-6 py-2">
        <div
          className="w-full text-sm py-2 px-4 text-white bg-[#193564] hover:bg-[#142c4f] rounded-lg transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-[#193564] focus:ring-opacity-50 block text-center"
        >
          Read More
        </div>
      </div>
    </div>
  );
}

export default Card;
