import { Card } from "@/components/index"


const CARD_DATA = [
    {
        title: "Customer Experience",
        description: "Drive Growth Through Customer Insights: Our market research unveils consumer preferences, behaviors, and satisfaction levels, empowering businesses to optimize customer experiences and fuel growth",
        gradient: "bg-gradient-to-r from-blue-500 to-teal-300 text-transparent bg-clip-text",
				image: '/images/python-logo.png'
    },
    {
        title: "New Product Development",
        description: "Inspire Innovation: Our market research delivers essential insights on market trends, customer needs, and competitors, fueling successful new product developments.",
        gradient: "bg-gradient-to-r from-orange-500 to-pink-500 text-transparent bg-clip-text",
				image: '/images/angularjs-logo.png',
    },
    {
        title: "Brand & Communication",
        description: "Craft Compelling Messages: Our market research unveils consumer perceptions and effective communication channels, empowering brands to connect meaningfully with their audience.",
        gradient: "bg-gradient-to-r from-indigo-800 to-purple-700 text-transparent bg-clip-text",
				image: '/images/JavaScript_logo.png',
    },
    
]

function Cards() {
  return (
    <div className="common-bg w-full py-20 mx-auto bg-[#D7E7FB]">
      <div className="text-center font-bold text-[#0E2152] text-[50px] mb-8 leading-normal">
        Latest Jobs
      </div>
      <div className="flex flex-col lg:flex-row justify-center items-center space-x-0 lg:space-x-6 space-y-8 lg:space-y-0">
        {CARD_DATA.map((card, index) => (
          <Card
            key={index}
            title={card.title}
            description={card.description}
            titleGradient={card.gradient}
            image={card.image}
            href={card.href}
          />
        ))}
      </div>
    </div>
  );
}


export default Cards